-- Seed data for a fresh dev database. Idempotent (ON CONFLICT DO NOTHING),
-- safe to run against an already-seeded database.
--
-- Matches the schema as of migration 000016 (add_volume_tracking). If this
-- starts failing with "column does not exist", the schema has moved on and
-- this file needs the same treatment.

-- Organization
INSERT INTO organizations (id, name, display_name)
VALUES (1, 'default', 'Default Organization')
ON CONFLICT (id) DO NOTHING;

-- Demo user: demouser / NewPassword123 (matches the hint shown on the
-- login page). Hash generated by the real backend's bcrypt.DefaultCost,
-- not hand-rolled, so it's guaranteed compatible with the login handler.
