    '$2a$10$t1V3E7xfEo5ZJnNP8Q.3wehFdBWV1qBAwA28ewkQrIIK2Xjs6AXN.',
    'admin',
    true
)
ON CONFLICT (username, organization_id) DO NOTHING;

